import { references } from "../data";
import { withBasePath } from "../basePath";

function Cite({ ids }: { ids: string[] }) { return <sup className="cite">{ids.map((id) => <a key={id} href={`#ref-${id}`}>{id.slice(1)}</a>)}</sup>; }

function referenceTypeEnglish(type: string) {
  const translated = type
    .replace(/Kodak片种数据|Kodak正片数据/g, "Kodak stock data")
    .replace(/Kodak技术读物|Kodak电影胶片参考指南/g, "Kodak technical guide")
    .replace(/Kodak处理规范|Kodak实验室控制|Kodak技术资料/g, "Kodak process / technical publication")
    .replace(/Eastman Kodak专利/g, "Eastman Kodak patent")
    .replace(/Adobe Systems专利/g, "Adobe Systems patent")
    .replace(/同期后期制作报道/g, "Period post-production report")
    .replace(/完成态参考/g, "Finished-state reference")
    .replace(/扫描器资料/g, "Scanner documentation")
    .replace(/官方标准|标准|规范/g, "Official standard")
    .replace(/研究/g, "Research")
    .replace(/实验逻辑/g, "Experimental method")
    .replace(/测量机制/g, "Measurement mechanism")
    .replace(/DGK Color Tools官方色卡说明与CIELAB参考值/g, "DGK official chart guide and CIELAB reference")
    .replace(/非5279配方|不是5279配方|不是5279常数|不是5279参数/g, "not a 5279 formula or parameter")
    .replace(/[（）]/g, (mark) => mark === "（" ? " (" : ")");
  return /\p{Script=Han}/u.test(translated) ? "Primary / technical source" : translated;
}

export function ResearchEnglish() {
  return (
    <main className="paper-page wrap">
      <header className="paper-header"><span className="eyebrow">RESEARCH NOTE · REVISION 2026.08 · V40</span><h1>From silver-halide sites<br />to a motion-picture image</h1><p className="abstract"><b>Abstract</b> — This project reconstructs Kodak VISION 500T 5279 image formation from digital RAW rather than copying a static LUT. V40 retains density formation, withdraws V39 colour randomness that lacked covariance/NPS evidence, and makes extreme tails plus native every-frame audits part of release.</p><div className="paper-byline"><span>LIVING RESEARCH RECORD</span><span>METHOD · EXPERIMENT · ERROR REVIEW</span></div></header>

      <div className="paper-layout">
        <aside className="paper-toc"><b>CONTENTS</b><a href="#v40">V40　Colour-grain covariance repair</a><a href="#v40-fsd-control-en">V40　Three-pipeline control</a><a href="#t003-chart-audit-en">T003　Chart input audit</a><a href="#t003-neutral-transport-en">T003　Neutral transport</a><a href="#v39">V39　Withdrawn density experiment</a><a href="#v38">V38　Display delivery boundary</a><a href="#v37">V37　Temporal grain formation</a><a href="#v36">V36　Matched 35 mm structure</a><a href="#v35">V35　Production validation</a><a href="#v34">V34　Pipeline audit</a><a href="#v33">V33　Input boundary</a><a href="#v32-en">V32　Measurement lock</a><a href="#premise">1　Premise</a><a href="#layers">2　Layered emulsion</a><a href="#grain">3　Grain and dye clouds</a><a href="#mask">4　Coloured mask</a><a href="#dir">5　DIR interimage</a><a href="#scanner">6　Scanner coupling</a><a href="#tone">7　Black and highlights</a><a href="#v21-en">8　V21 structure</a><a href="#v22-en">9　V22 colour</a><a href="#v23-en">10　V23 morphology</a><a href="#v24-en">11　V24 35 mm spectrum</a><a href="#v25-en">12　V25 output standard</a><a href="#v26-en">13　V26 grain NPS</a><a href="#v27">14　V27 scan calibration</a><a href="#v28-en">15　V28 RAW input</a><a href="#v29-en">16　V29 full motion</a><a href="#v30-en">17　V30 colour evidence</a><a href="#v31-en">18　V31 normal process</a><a href="#evidence-audit-en">Evidence audit</a><a href="#limits-en">Limits</a><a href="#references">References</a></aside>
        <article className="paper-body">
          <section id="v40"><div className="section-tag">27 · V40 · COLOUR-GRAIN COVARIANCE REPAIR</div><h2>Correct marginal RMS can still produce completely wrong colour noise</h2><p>V39&apos;s broken-TV primary speckles are present in the local 12-bit masters; they are not a web H.264 or player illusion. The release audit constrained each record&apos;s 48 µm RMS and mean colour, but not cross-record covariance, skew, extreme tails or the observer&apos;s integration of high-frequency opponent colour. More fundamentally, the 5279 sheet measures processed film and cannot uniquely invert stochastic dye yield in nine pre-DIR speed layers. Public 2383 material likewise supplies no exposure-conditioned record covariance or NPS.<Cite ids={["R1", "R4", "R7", "R25", "R58"]} /></p><div className="equation"><span>COMPLETE STOCHASTIC BOUNDARY</span><b>Evidence = RMS + Covariance + Tail + Observer</b><small>Marginal variance alone does not define a colour-film grain image.</small></div><p>V40 retains density-domain 5279/2383 MTF, accepted colour, H-D, black, gamma and independent framewise sites. It restores the 48 µm constraint after stochastic DIR at the processed-negative boundary, restores opponent integration in both scan and print observers, and withdraws unsupported independent 2383 Poisson records plus V39&apos;s signed intermediate film-RGB cancellation. A second audit then found that the historical V31 final adapter re-added the complete projection opponent high-frequency residual after the observer had already integrated it; V40 explicitly sets that duplicate retention to zero while preserving projection luminance and restrained scan-derived low-frequency dye colour. Every web image derives from the encoded professional master through its sRGB viewing companion, so there is no second still-render path.</p><p>Silver Efex offers directional evidence, not 5279 parameters. DxO separates generic grain from dozens of branded models based on analyzed real films; the film type owns a grain model while the user varies intensity and size. DxO also states that its calibrated profiles avoid universal Gaussian noise, derive complex grain matrices from real silver-halide crystals, and analyze different behavior in shadows, midtones and highlights. Its official controls connect coarser grain with perceived detail/sharpness. That supports our premise that finite grain reconstructs the image and morphology belongs to a stock. Silver Efex is a monochrome still engine, however, with neither colour-record covariance nor motion-picture frame constraints, so it cannot be transplanted directly.<Cite ids={["R63", "R64", "R65"]} /></p><ol className="research-plan"><li><b>V39 formally withdrawn</b><span>The failed image remains archived but is no longer a baseline.</span></li><li><b>Unknown terms become zero</b><span>Intrinsic stochastic 2383 grain waits for covariance/NPS measurement.</span></li><li><b>Native every-frame audit</b><span>All 144 delivered 5760×4320 frames across three scenes and two branches are tested.</span></li><li><b>Silver Efex black-box next</b><span>Gray-ramp, flat-field and edge probes inform V41 research only; they do not backfill V40.</span></li></ol></section>
          <section id="v39"><div className="section-tag">26 · V39 · DENSITY-FORMATION RECONSTRUCTION</div><h2>Grain is the formed density image—not a display-space residual</h2><p>V39 is a domain correction, not a new look. The previous graph fitted Kodak&apos;s processed-stock MTF but applied it after the negative had already become a positive display image; the 2383 MTF function likewise acted on a display residual despite its density-domain name. The 5279 finite-site residual was normalized after stochastic DIR, and the remaining 2383 texture was introduced as a display-luminance ratio. Those operations could match isolated statistics while breaking the causal order of exposure, development, printing and observation.</p><div className="equation"><span>V39 FORMATION ORDER</span><b>MTF<sub>5279</sub>(D<sub>mean</sub>) + δD<sub>sites</sub> → scan / D<sub>2383</sub> → MTF<sub>2383</sub> + δD<sub>print</sub> → observer</b><small>Every image-structure operation now acts on a density-bearing state before the corresponding scanner or projected-light observer.</small></div><p>The official 48 μm diffuse-RMS target is now a calibration of developed dye yield before stochastic DIR transport. Its gain is predicted from the destination aperture variance, so DIR remains free to alter local covariance rather than being erased by a final residual rescale. A neutral 18% flat test returns R/G/B aperture RMS within about 0.3% of the published-target interpolation. The RAW boundary is corrected at the same time: signed wide-gamut components may pass through the BT.2020-to-film-record matrix, while physically non-negative record exposures are clamped only afterwards. This affects roughly 0.29–1.11% of pixels in the three measured scenes, mainly deep shadows; it is not a global colour grade.<Cite ids={["R1", "R4", "R7", "R25", "R44", "R45", "R47", "R58"]} /></p><ol className="research-plan"><li><b>Negative structure in negative density</b><span>The processed 5279 MTF filters scene modulation in mean density; the separately calibrated finite-site density residual joins it before Spirit aperture or print exposure.</span></li><li><b>Print structure in print density</b><span>2383 MTF and three-record fine-grain dye-cloud variance are formed in Status-A print density; there is no final display-noise overlay.</span></li><li><b>Freeze accepted colour</b><span>5279 dye spectra, H-D curves, mask, 2383 LAD, scan neutrality, black, gamma and both display exits are not artistically retuned.</span></li><li><b>State the remaining boundary honestly</b><span>The monitor projection is still a scan-referenced, low-frequency empirical adaptation. Public documents do not uniquely identify an exact 2000s theatrical print/projection chain.</span></li></ol></section>
          <section id="v38"><div className="section-tag">25 · V38 · REFERENCE-DISPLAY DELIVERY</div><h2>One linear observer image needs two explicit display exits</h2><p>The V37 movie appearing richer in QuickTime than its JPEG still did not mean that 5279 colour or grain changed in motion. Both came from the same frame, but BT.709/BT.1886 video and the macOS sRGB still-image path interpreted it through different transfer functions. V38 freezes the complete V37 image model and forks only the final encoding of one linear Rec.709 observer result.</p><div className="equation"><span>V38 DISPLAY CONSISTENCY</span><b>EOTF<sub>BT.1886</sub>(V<sub>master</sub>) ≈ EOTF<sub>sRGB</sub>(V<sub>Mac</sub>) ≈ L<sub>observer</sub></b><small>Observed light remains the same even though encoded code values differ.</small></div><p>The professional file is 12-bit ProRes 4444 Rec.709 1-1-1 for the XDR “HDTV Video (BT.709–BT.1886)” reference mode. The direct-view Mac companion retains Rec.709 primaries and matrix but uses the sRGB transfer and MOV 1-13-1, sharing the same display boundary as the web JPEG. P3 cannot recover colours absent from a Rec.709 observer, while HDR would change contrast and highlight intent, so neither is silently introduced.<Cite ids={["R26", "R27", "R60", "R61", "R62"]} /></p><ol className="research-plan"><li><b>Freeze image formation</b><span>Colour, H-D, black, gamma, MTF, DIR, grain and both observers remain V37.</span></li><li><b>One in-memory source</b><span>Both ProRes encodes come directly from the same linear observer array without an intermediate video decode.</span></li><li><b>One still source</b><span>The web still is generated from the direct-view companion at the same representative frame.</span></li><li><b>Verify delivery intent</b><span>Every file is audited for 12-bit pixels, colour metadata, frames, audio, timecode and linear-light round-trip error.</span></li></ol></section>
          <section id="v37"><div className="section-tag">24 · V37 · INDEPENDENT SITES / STABLE INTEGRATION</div><h2>Authentic framewise randomness does not require the whole imaging operator to breathe</h2><p>The overlay-like boil remained visible in the local 12-bit QuickTime master, so it was not only a web H.264 artifact. Each motion-picture frame exposes a different area of emulsion; smoothing, freezing or advecting grain across frames would manufacture another digital behavior. V36 sites were already independent. The redundant motion came from drawing one whole-field phase for each record and speed population, rotating the bilinear subpixel integration operator and moving its high-frequency amplitude and x/y preference together from frame to frame.</p><div className="equation"><span>V37 TEMPORAL BOUNDARY</span><b>G<sub>t</sub> ⟂ G<sub>t+1</sub>　·　K<sub>integration,t</sub>=K<sub>integration</sub></b><small>The emulsion realization renews independently; the numerical operator keeps a stable statistical transfer.</small></div><p>A flat-field ablation changed phase only. Per-frame random phase gave about 0.64% high-pass RMS coefficient of variation versus 0.09% for the stable control; x/y anisotropy standard deviation fell from about 0.0596 to 0.0050. Native eight-frame T031 probes then tested 0, 30 and 90 degrees. Zero left a fixed raster preference and 90 over-corrected. At 30 degrees, mean anisotropy shifts by only +0.00596 in projection and +0.00359 in scan; projection high-pass CV falls to 0.400× V36 and directional variation to 0.287×.<Cite ids={["R21", "R58", "R59"]} /></p><p>Frame remains part of every Philox identity, so all 45 site groups renew on every frame. Only the 15 record/speed/size-class phases become a golden-ratio ensemble rotated by 30 degrees. Colour, H-D, black, gamma, MTF, DIR, 48 μm RMS, grain size and both observers remain unchanged. The first claim of very large V35 T031 tail differences came from comparing frames 0–23 with 132–155 and is withdrawn; V37 does not use invalid evidence against the Production sampler.</p><ol className="research-plan"><li><b>Keep true independence</b><span>No temporal filtering, fixed grain plate or motion-vector advection.</span></li><li><b>Remove the second animation</b><span>The operator phase is stable while the stochastic emulsion renews.</span></li><li><b>Ablate phase</b><span>Thirty degrees passes both temporal stability and mean-direction neutrality.</span></li><li><b>Change one thing</b><span>Colour, density, sharpness, grain scale and viewing conditions remain frozen.</span></li></ol></section>
          <section id="v36"><div className="section-tag">23 · V36 · MATCHED FRAME / 35 MM STRUCTURE</div><h2>Grain constitutes the image, but density itself is not sharpness</h2><p>V35 T007 and T031 incorrectly used frames 0–23, while V34 used 276–299 and 132–155. Different source motion and texture appeared as a film-version change. V36 makes absolute source frames a release gate: camera, projection, scan, still and hover video must use one window. The first V36 salt screen repeated the frame-0 error and has been invalidated rather than used for tuning.</p><p>At the correct T031 frame 132, Philox with Archive spatial kernels gives V34 ratios of 1.00121 for median high-pass RMS, 1.00139 for temporal-difference RMS and 1.00131 for grain/base-edge. Archive sampling with Production spatial kernels essentially reproduces V34 pixel for pixel. V36 therefore adds no softening, grain reduction, colour, black, gamma, MTF or DIR change.</p><div className="equation"><span>ONE DENSITY IMAGE</span><b>D<sub>realized</sub>(x,y)=D<sub>mean</sub>(x,y)+δD<sub>grain</sub>(x,y)</b><small>This is a statistical decomposition of one formed image—not noise overlaid after rendering.</small></div><p>Density D=−log₁₀T is the image variable. Sharpness is the spatial transfer of density modulation, described by MTF or edge spread. Kodak publishes processed-stock MTF and 48 μm diffuse RMS granularity as separate image-structure measures; E-58 adds negative noise frequency, negative and print granularity, both MTF stages and magnification as joint determinants of visible graininess. At 24.9 mm/5760, the 48 μm aperture spans 11.10 pixels; fitted MTF50 is approximately R 51.12, G 64.75 and B 72.26 cycles/mm.<Cite ids={["R1", "R21", "R25"]} /></p><ol className="research-plan"><li><b>Match time first</b><span>T002 0–23, T007 276–299 and T031 132–155 are mandatory comparison keys.</span></li><li><b>Then measure space and time</b><span>NPS, edges and frame differences are interpreted only after scene motion aligns.</span></li><li><b>One physical scale</b><span>MTF and granularity remain distinct measurements that jointly constrain a 35 mm result.</span></li><li><b>Reject the wrong fix</b><span>A correct 5279 model is not blurred to compensate for an invalid comparison.</span></li></ol></section>
          <section id="v35"><div className="section-tag">22 · V35 · AUDITABLE PRODUCTION GRAPH</div><h2>Grain statistics may be independent, but they may not be anonymous</h2><p>V35 does not change the V34 photographic model. It moves the most expensive finite-site draw to Philox4x32-10: every random word is identified by frame, record, speed population, size class and global pixel coordinate, independent of thread, tile or request order. The first 24-bit inverse-CDF candidate passed statistical tests but could not honestly be called mathematically exact. The final path compares a complete uint32 word directly with <code>floor(float32 p × 2³²)</code>. Across the observed three-source domain, p spans 1.685×10⁻⁷—0.986325 and the maximum threshold representation error is 2.269×10⁻¹⁰.<Cite ids={["R56"]} /></p><div className="equation"><span>FINITE-SITE IDENTITY</span><b>seed=30M+10k·frame+1k·record+100·population+class</b><small>All 45 calls per frame must be unique; 1,080 calls across 24 frames produced zero duplicates.</small></div><p>Asynchronous Metal draws overlap CPU expectation filtering, and the V31 colour adapter reuses full-frame buffers. Unsafe Numba workqueue observer concurrency is rejected before decode. T002 renders both masters in 26.200 seconds per frame, 23.65% faster than V34. Four full emulsion seeds give layer standard-deviation ratios 0.999918/1.000264/0.999852; the NPS delta is smaller than ordinary reference seed variation.<Cite ids={["R50", "R54", "R57"]} /></p><p>Release validation no longer examines one centre crop or mean RGB alone. Five regions over 24 frames measure luma tails, low/high clipping, RGB high-pass covariance, spatial grain energy and frame-difference energy. Projection and scan pass every gate with no systematic green, blue or magenta shift. Two algebraically equivalent convolution rewrites save 0.65–0.9 seconds but let ~5×10⁻⁶ density reorder reach isolated 900–960/65535 projection-code differences through 2383 thresholds, so both are rejected. Speed cannot cross the rare-event quality boundary.</p><ol className="research-plan"><li><b>Separate Archive and Production</b><span>V34 stays byte-exact; V35 permits an independent but constrained realization.</span></li><li><b>Trace every stochastic identity</b><span>Source, algorithm, profile, LUT, command and all 45 calls per frame enter provenance.</span></li><li><b>Tails are image quality</b><span>A small average error cannot hide rare large changes at nonlinear 2383 thresholds.</span></li><li><b>Full-frame OFX first</b><span>v1 uses the host Metal queue, serial per instance and supportsTiles=false until halo behavior is proven.</span></li></ol></section>
          <section id="v34"><div className="section-tag">21 · V34 · PROCESSED MTF / SINGLE GENERATION</div><h2>Developer adjacency is not a sharpness effect that can be stacked twice</h2><p>Kodak's 5279 sheet states that MTF, resolving-power and granularity data were generated from tungsten-exposed film processed in recommended ECN-2. Kodak's reference guide also says MTF above 100% commonly results from developer adjacency. The published graph is therefore a total processed-stock response, not an optical blur waiting for another DIR stage. The old model added V21 deterministic intralayer adjacency and then applied a kernel already fitted to the complete graph. Neutral sinusoid tests found about 1–3.5% excess at some channel/frequency combinations. V34 removes only that deterministic duplicate. Interimage transport, stochastic dye-cloud coupling, the three speed populations and 48 μm RMS remain frozen.<Cite ids={["R1", "R21"]} /></p><div className="equation"><span>V34 MTF OWNERSHIP</span><b>MTF<sub>det,out</sub>(f)=MTF<sub>Kodak, processed</sub>(f)</b><small>No second deterministic DIR-adjacency multiplier; stochastic NPS stays frozen without 5279 spectrum measurements.</small></div><p>V31 also encoded V30 projection and scan, decoded both for the OKLab low-frequency chroma boundary, then encoded projection again. It was deterministic but not lossless. V34 lets both observers output linear Rec.709, runs the unchanged low-frequency scan a/b plus projection opponent residual and exact projection Y in memory, then encodes each result once. A pipeline-only scan probe is file-SHA-256 identical to V30. Projection changes come from removing an unnecessary lossy generation and the duplicated MTF—not from saturation, lifted blacks or a new gamma.</p><div className="equation"><span>SINGLE-GENERATION BOUNDARY</span><b>Encode<sub>proj</sub>(A(Proj<sub>lin</sub>,Scan<sub>lin</sub>))　·　Encode<sub>scan</sub>(Scan<sub>lin</sub>)</b><small>A remains the V31 adapter; there is no longer Encode→Decode→A→Encode.</small></div><p>Skipping nine zero-contribution full-frame Gaussians left both T020 master SHA-256 values unchanged and reduced the old ~43.5 s/frame V30+V31 path to about 36.1 s/frame in V34. Two workers reached 28.85 s/frame but created roughly 6.6 GiB of swap and were rejected on the 48-GiB Mac. Future major speedups belong to a resident Metal/OpenFX graph, host command queues, temporary-resource reuse and asynchronous submission—not weakened PCG64 statistics, border support or 12-bit delivery.<Cite ids={["R54", "R55"]} /></p><ol className="research-plan"><li><b>No colour retune</b><span>White balance, saturation, black, gamma and the Technical Neutral boundary do not change.</span></li><li><b>No guessed grain</b><span>Without a 5279 NPS, size distributions and temporal statistics remain frozen.</span></li><li><b>Processed MTF once</b><span>The official total response remains; only the later deterministic duplicate is removed.</span></li><li><b>Encode once</b><span>Each 12-bit Rec.709 1-1-1 master receives one ProRes generation.</span></li></ol></section>
          <section id="v33"><div className="section-tag">20 · V33 · CAMERA INPUT / BLACK BOUNDARY</div><h2>A mild green direction is not a constant that taste can safely invert</h2><p>FCP Standard and the camera baseline share the same broad direction on aligned T031; official V-709 adds a smaller observer difference in low-chroma regions. A mathematical neutral remains neutral through linear BT.2020→V-Gamut, V-Log and official V-709, with only 0.000589 maximum channel spread. V33 therefore adds no magenta term to 5279. As Shot 0.00 stop becomes an independent witness, +0.45 stop is explicitly virtual film EI, and Technical Neutral remains disabled until a same-light gray card or ColorChecker authorizes it.<Cite ids={["R44", "R45", "R46", "R47", "R49"]} /></p><div className="equation"><span>INPUT BOUNDARY</span><b>Camera<sub>witness</sub>=V709(RAW, 0.00 stop)　·　Film<sub>input</sub>=RAW·2<sup>0.45</sup></b><small>If a neutral target proves a systematic residual, correction belongs before 5279 exposure—not inside film, print or scan.</small></div><p>Black is now measured with encoded Rec.709 luma ≤1/1023, alongside 0–1% linear toe occupancy, p05–p95 contrast, a 32-bin robust tone curve and effective camera-to-observer log-luma power. Projection hard black is about 0–0.0013%; scan hard black is nearly zero on T007 and 1.820%/1.349% on darker T002/T031. Both observers remain monotonic on all three scenes.</p><ol className="research-plan"><li><b>Pixels frozen</b><span>Accepted V31/V32 projection and scan masters are reused byte for byte.</span></li><li><b>Partial delivery</b><span>A 24-frame audio test contains exactly 48,048 samples at 48 kHz; timecode advances by absolute source frames.</span></li><li><b>Memory safety</b><span>Three concurrent 5.7K float witnesses created unacceptable pressure on the 48-GiB machine. One native Archive-Exact worker is now the safe default; image kernels do not change.</span></li><li><b>Next evidence</b><span>A same-light gray card/ColorChecker will decide whether Technical Neutral exists and how strong it may be.</span></li></ol></section>
          <section id="v32-en"><div className="section-tag">19 · V32 · MEASUREMENT-FIRST GENERALIZATION</div><h2>Once the image is accepted, the next version first stops changing it</h2><p>V32 freezes V31’s 5279 emulsion, nine stochastic sublayers, DIR, MTF, 2383 LAD, scan observer, black, gamma and normal-process chroma boundary. T007 and T031 each contribute 24 native-resolution frames under the same +0.45-stop input and one parameter set. Water highlights, fine grass, neutral stone, warm mushrooms and dark leaves become independent generalization tests—not grading targets.</p><div className="equation"><span>V32 FREEZE</span><b>Image<sub>V32</sub>(x,y,t) = Image<sub>V31</sub>(x,y,t)</b><small>Only measurement, format, delivery and plugin-migration contracts change.</small></div><p>Every Rec.709 master passes 24-frame, 5760×4320, ProRes 4444, 12-bit and complete 1-1-1 gates. Temporal QA measures frame mean, p99 highlights, hard clipping, texture RMS and the near-neutral axis. The V31 adapter is compared as a full frame and an OFX halo tile: σ=0.72×width/2048 and halo=ceil(6σ), so proxy or tile width cannot change the crossover scale.</p><p>Cinema delivery no longer uses the P3-D65/gamma-2.6 ProRes probe. V32 follows SMPTE ST 428-1: a 24fps, 2880×2160 uncompressed DCDM stores 12-bit X′Y′Z′ in the high 12 bits of 16-bit TIFF words and validates low bits, names, dimensions, count and round trip. It is the lossless sequence before DCP packaging—not a new look or invented gamut.<Cite ids={["R26", "R28", "R32", "R53"]} /></p><ol className="research-plan"><li><b>P3 ProRes rejected</b><span>MOV atoms, frame headers and players do not consistently express the same RGB meaning.</span></li><li><b>Quality first</b><span>Stochastic emulsion and spectral observation dominate runtime; encoding is about 0.38–0.58 seconds/frame/worker.</span></li><li><b>Plugin boundary</b><span>Seeds use absolute source frames; Archive Exact remains authoritative until GPU parity passes.</span></li><li><b>New evidence</b><span>Two dissimilar scenes require no per-shot parameters, evidence that the baseline generalizes.</span></li></ol></section>

          <section id="premise"><div className="section-tag">01 · PREMISE</div><h2>The image does not exist first and acquire grain later</h2><p>Digital noise is usually treated as a disturbance added to a regular pixel sample. Film randomness occurs earlier: whether photons create a developable latent image in a finite silver-halide crystal determines whether dye will form at that location. Density and grain are therefore two observations of the same population of events.<Cite ids={["R2", "R3", "R13"]} /></p><blockquote>Image density is the optical observation of many discrete development events.</blockquote><p>The baseline reconstructs film, print and scan behaviour. Lift, saturation and aesthetic contrast remain external creative decisions.</p></section>

          <section id="layers"><div className="section-tag">02 · LAYERS</div><h2>Each colour record contains more than one speed layer</h2><p>Blue-, green- and red-sensitive records form yellow, magenta and cyan dyes. Within every record, overlapping fast, medium and slow emulsions trade sensitivity for granularity. Faster populations usually require larger effective crystals and dominate low exposure; slower, finer populations increasingly carry highlights.<Cite ids={["R2", "R7", "R15"]} /></p><div className="layer-diagram" aria-label="Simplified emulsion stack"><div className="coat">Protective / UV layer</div><div className="blue"><b>Blue-sensitive record</b><span>fast · medium · slow → yellow dye</span></div><div className="filter">Yellow filter layer</div><div className="green"><b>Green-sensitive record</b><span>fast · medium · slow → magenta dye</span></div><div className="inter">Interlayer / scavenger</div><div className="red"><b>Red-sensitive record</b><span>fast · medium · slow → cyan dye</span></div><div className="base">Base + rem-jet</div></div><p>The record-specific sizes used by the model are same-era structural priors, not a claim to Kodak’s undisclosed 5279 coating. Final R/G/B amplitude and resolution are normalized to the published 48 µm RMS and MTF measurements.</p></section>

          <section id="grain"><div className="section-tag">03 · GRAIN</div><h2>The processed colour negative contains dye clouds, not retained silver</h2><p>Colour development reduces exposed halide to silver while oxidized developer forms insoluble dye. Bleach and fixer subsequently remove the silver image. Printing and scanning observe dye clouds and the retained coloured mask.<Cite ids={["R2", "R3", "R15"]} /></p><div className="process-strip"><span>Exposure</span><i>→</i><span>Latent sites</span><i>→</i><span>Silver development + dye formation</span><i>→</i><span>Bleach / fix</span><i>→</i><b>Dye-cloud image</b></div><div className="equation"><span>FINITE SITES</span><b>Var(f) = p(1 − p) / n</b><small>Variance falls when a population is almost unexposed or almost fully developed and peaks through its transition.</small></div></section>

          <section id="mask"><div className="section-tag">04 · MASK</div><h2>The orange base is the constant remainder of imagewise colour correction</h2><p>Real cyan and magenta dyes have unwanted side absorptions. Coloured masking couplers are consumed in the opposite direction during dye formation, approximately flattening those absorptions across a band. The 5279 data-sheet curves marked “D-mins subtracted” are signed net-density changes, not isolated positive dye spectra.<Cite ids={["R1", "R2", "R3"]} /></p><div className="equation"><span>NET SPECTRAL DENSITY</span><b>ΔD<sub>net</sub>(λ) = D<sub>dye</sub>(λ) − D<sub>mask consumed</sub>(λ)</b><small>Residual mismatch after band-average correction contributes to a stock’s colour character.</small></div></section>

          <section id="dir"><div className="section-tag">05 · DIR</div><h2>Local sharpness and saturation share one chemical mechanism</h2><p>Development-inhibitor-releasing couplers emit inhibitors where development occurs. Lateral transport can create adjacency and acutance; transport into neighbouring records changes the relationship between neutral and separation exposure. Layer placement, barriers, scavengers and release timing all matter.<Cite ids={["R6", "R11"]} /></p><div className="equation"><span>SEPARATION INDEX</span><b>S<sub>c</sub> ≈ γ<sub>separation,c</sub> / γ<sub>neutral,c</sub></b><small>Saturation is record-, exposure-, neighbourhood- and layer-dependent—not a global HSV knob.</small></div><p>The current matrix is a bounded phenomenological model. Hourly research found that Kodak’s published DIR diffusion-factor assay is compound-specific and cannot be reinterpreted as a measured 5279 3×3 coefficient.</p></section>

          <section id="scanner"><div className="section-tag">06 · SCANNER</div><h2>A Status-M densitometer is not a period telecine</h2><p>Status-M defines the measurement axis for sensitometry and granularity. A telecine has its own lamp, filters, broad detector responses, film matching and electronic primary correction. Same-era Kodak work documents red-channel dye cross-talk and film designs pre-compensated for electronic transfer.<Cite ids={["R11", "R12"]} /></p><div className="observer-grid"><div><b>Status-M</b><span>NARROW STANDARD DENSITY</span><small>Data-sheet measurement only</small></div><div><b>Period 2K</b><span>BROAD DETECTORS + FILM MATCH</span><small>DI / Cineon result</small></div><div><b>2383 print</b><span>PRINTER LIGHT + PRINT RECORDS</span><small>Projection positive</small></div></div><p><i>Charlie’s Angels: Full Throttle</i> is a valuable 2003 finished-state reference because it used 5279 and a 2K DI, but its creative grade, post pipeline and later home-video transfer are not bare-stock measurements.<Cite ids={["R9", "R10"]} /></p></section>

          <section id="tone"><div className="section-tag">07 · TONE</div><h2>Black, highlights, grain and curve slope must be calibrated together</h2><p>Projection black is limited by 2383 maximum density, projector/room flare and screen luminance. Blu-ray black is created by scan density, Cineon mapping, signal transfer and display behaviour. One lift/gamma/gain curve cannot make these distinct chains physically identical.</p></section>

          <section id="v21-en"><div className="section-tag">08 · V21</div><h2>Development, structure and observers move into their proper domains</h2><ol className="research-plan"><li><b>Neutral invariance</b><span>Population-domain DIR vanishes on a uniform field; H-D drift fell to roughly 2.4×10⁻⁷ D.</span></li><li><b>Record-specific morphology</b><span>Cyan-, magenta- and yellow-forming records receive different fast/mid/slow cloud scales and site counts.</span></li><li><b>Three observers</b><span>Status-M measures; a broad period observer scans; 5279 transmission and 2383 form the print.</span></li></ol></section>

          <section id="v22-en"><div className="section-tag">09 · V22 · ANALYTICAL DYES</div><h2>Status-A density cannot be reused as dye amount</h2><p>Status-A integrates overlapping print-dye absorption under standard weights. V22 numerically inverts principal curves to analytical dye amounts, applies print interimage around LAD and then forms 2383 density. A neutral-subtracted D60 vendor target contributes relative OKLab a/b only, never an absolute tint.<Cite ids={["R16", "R17", "R18", "R19", "R20"]} /></p></section>

          <section id="v23-en"><div className="section-tag">10 · V23 · DYE-CLOUD FIELD</div><h2>More organic does not mean coarser or louder</h2><p>Five size classes, golden-angle subpixel phases and a restrained large-cloud tail approximate a continuous dye-cloud population while every record remains normalized to the published 48 µm RMS. T020 and T032 provide cross-scene RAW holdouts.<Cite ids={["R1", "R7", "R21", "R22", "R23", "R24"]} /></p></section>

          <section id="v24-en"><div className="section-tag">11 · V24 · 35 MM SPECTRAL SEPARATION</div><h2>Why V23 could still resemble early CCD or 16 mm</h2><p>Gauge appearance depends on magnification, low-frequency power and the complete negative/print/scan MTF—not only one aperture RMS number. V24 shifts cloud power to finer scales and integrates opponent-colour grain separately in projection and scan observers while preserving luminance grain and deterministic RGB.<Cite ids={["R1", "R4", "R21", "R22", "R25"]} /></p><div className="equation"><span>OBSERVED GRAIN</span><b>NPS<sub>out</sub>(f) ≈ NPS<sub>neg</sub>(f)|MTF<sub>chain</sub>(f)|² + NPS<sub>print/scan</sub>(f)</b></div></section>

          <section id="v25-en"><div className="section-tag">12 · V25 · OUTPUT STANDARD</div><h2>Viewing conditions are not source-file transfer functions</h2><p>The first V25 export incorrectly baked inverse display EOTFs into Rec.709-tagged files. The corrected release delivers both monitor masters with Rec.709 OETF and complete 1-1-1 metadata. Gamma 2.6 remains inside the cinema observer; BT.1886 remains a reference-display EOTF; web proxies explicitly convert decoded Rec.709 light to sRGB.<Cite ids={["R26", "R27", "R28", "R29", "R30", "R31", "R32"]} /></p></section>

          <section id="v26-en"><div className="section-tag">13 · V26 · EXPOSURE-CONDITIONED GRAIN NPS</div><h2>Fine 35 mm grain does not use one texture at every exposure</h2><p>Fast, medium and slow populations receive distinct five-class cloud distributions. Exposure determines which population supplies local variance; the published 5279 RMS determines the integrated amplitude. Colour, tone, MTF, DIR and both observers remained V25.</p><div className="diagnostic-grid"><figure><img src={withBasePath("/research/v26-grain-nps.png")} alt="V25 and V26 normalized radial grain spectra" /><figcaption>Normalized green-record NPS: shadows move slightly lower in frequency while highlights become finer.</figcaption></figure><figure><img src={withBasePath("/research/v26-layer-variance-activation.png")} alt="Fast medium and slow variance contribution over exposure" /><figcaption>p(1−p) selects speed layers through exposure rather than changing post-noise strength.</figcaption></figure></div></section>

          <section id="v27"><div className="section-tag">14 · V27 · PERIOD-SCAN NEUTRAL SCALE</div><h2>The green veil was a real density-dependent scanner calibration error</h2><p>V26 balanced the period scan at 18% gray and one high-density anchor while deliberately retaining 18% of an assumed scanner/dye residual. Neutral diagnostics showed a green hump in shadows and lower midtones, exact neutrality at the single 18% anchor, and a change of bias direction above mid-gray. The web Rec.709→sRGB path and V26 grain were not responsible.</p><div className="equation"><span>NEUTRAL-SCALE CONSTRAINT</span><b>RGB′(x) = C<sub>Y(x)</sub>[RGB(x)]　with　Y(RGB′) = Y(RGB)</b><small>A dense neutral scale supplies level-dependent RGB balance. Every pixel retains its incoming Rec.709 luminance, so the correction cannot become lift, contrast or gamma.</small></div><div className="diagnostic-grid"><figure><img src={withBasePath("/research/v27-scan-neutral-axis.png")} alt="V26 and V27 period scan neutral-axis residual" /><figcaption>Maximum neutral channel residual fell from about 0.0182 to 0.00236; projection drift is exactly zero.</figcaption></figure></div><ol className="research-plan"><li><b>Green-opponent residual</b><span>Maximum magnitude fell from about 0.0217 to 0.00242 over display-linear Y 0.005–0.90.</span></li><li><b>Luminance preservation</b><span>Maximum numerical drift is below 1.8×10⁻⁷ before output encoding.</span></li><li><b>Projection lock</b><span>The 2383 projection result is numerically and byte-for-byte the V26 master.</span></li><li><b>Rejected alternative</b><span>Forcing complete primary separation made the real RAW frame greener and brighter, so it was not adopted.</span></li><li><b>Hourly boundary</b><span>The certified April 2003 provisional does name 5279 as identifier 3; May 2003 H022 substitutes 5218 and the later patent returns to 5279. This is document-branch drift, not a numerical calibration payload. No new 5279 NPS or DIR coefficient was recovered, so grain and chemistry remain V26.<Cite ids={["R38", "R39", "R41"]} /></span></li></ol></section>

          <section id="v28-en"><div className="section-tag">15 · V28 · PRORES RAW INPUT CONTRACT</div><h2>The second green veil came from a misplaced Camera LUT stage</h2><p>The decoder's Core Video attachments identify its float RGB buffer as extended-linear BT.2020/D65. V27 encoded that already converted RGB as V-Log and then applied Panasonic's RAW-Gamut-to-V-Gamut Camera LUT, effectively asking a nonlinear camera separation to interpret BT.2020 primaries as unseparated RAW Gamut.<Cite ids={["R44", "R45", "R46", "R47"]} /></p><div className="equation"><span>V28 INPUT TRANSFORM</span><b>RGB<sub>V-Gamut</sub> = M<sub>XYZ→V-Gamut</sub> · M<sub>BT.2020→XYZ</sub> · RGB<sub>Apple linear</sub></b><small>No V-Log transfer lies between the matrices, and no second white balance is introduced.</small></div><ol className="research-plan"><li><b>Not a minus-green grade</b><span>Lift, gamma, gain, saturation and colour temperature remain untouched.</span></li><li><b>Two-scene holdout</b><span>T020 scan near-neutral G/R falls from 1.04294 to 1.02895; T032 falls from 1.06476 to 1.04777 while retaining its genuine rainy cyan-green source colour.</span></li><li><b>Both observers recomputed</b><span>The error precedes 5279 exposure, so neither the print nor scan result can reuse V27 pixels.</span></li><li><b>Tone boundary</b><span>p99–p99.9 luminance is essentially unchanged, no new white clipping appears, and a synthetic uniform gray remains neutral.</span></li><li><b>Film lock</b><span>5279 sensitometry, dyes, DIR, grain NPS, MTF, 2383, Spirit, black and gamma remain V27.</span></li><li><b>Lossless acceleration</b><span>The 193³ analytical print lattice is hash-validated; decoded RGB48 hashes from both accelerated 12-bit masters are bit-identical to the reference path.</span></li></ol></section>

          <section id="v29-en"><div className="section-tag">16 · V29 · FULL-MOTION VALIDATION</div><h2>The final 15–20 percent cannot be completed by adding flavour</h2><p>H-1-5279t directly constrains neutral H-D, MTF and per-record RMS through a 48 µm aperture. It does not disclose a frequency-resolved NPS, the real three-layer recipe, a 5279-specific DIR matrix or Spirit's proprietary spectrum. V29 therefore retains V28 image formation and implements the measurable remainder as complete-motion and delivery validation.<Cite ids={["R1", "R7", "R8", "R21", "R22", "R34", "R35", "R36", "R37"]} /></p><div className="equation"><span>FINITE SITES AND RMS CONSTRAINT</span><b>Var(p̂)=p(1−p)/N　　D<sub>formed</sub>=D<sub>mean</sub>+δD·σ<sub>5279</sub>(logE)/σ<sub>pred</sub>(logE)</b><small>48 µm RMS fixes aperture-integrated amplitude; it does not uniquely invert a two-dimensional grain spectrum.</small></div><ol className="research-plan"><li><b>All 165 frames</b><span>Every T002 frame passes through the negative, 2383 and Period 2K observers.</span></li><li><b>Absolute-frame seeds</b><span>Parallel ranges form new emulsion by source-frame number; boundaries never reset, loop or translate a grain plate.</span></li><li><b>Motion gates</b><span>Black, white clipping, high-frequency RMS and successive-frame correlation are checked across the complete source. This is a scene stress test, not a claimed 5279 NPS measurement.</span></li><li><b>Bit-exact boundary</b><span>Full-master frame 82 is exactly equal to the independent frame-82 probe in decoded RGB48.</span></li><li><b>Validation result</b><span>165/165 frames pass; hard white clipping is zero for both observers, and audio, timecode and Rec.709 1-1-1 signalling are intact.</span></li><li><b>Compute result</b><span>Both native-resolution masters took 3113.17 seconds (51m 53.17s) in parallel, or 18.87 seconds per source frame.</span></li><li><b>Next evidence</b><span>Replacing the remaining priors requires paired 5279/GH7 spectral charts, neutral/separation wedges, controlled ECN-2 and high-resolution scanner data.</span></li></ol></section>
          <section id="v30-en"><div className="section-tag">17 · V30 · THREE-SCENE COLOUR EVIDENCE</div><h2>The blue-magenta veil was a traceable calibration error, not a projection look</h2><p>H-61B publishes unequal 2383 LAD aims: 1.09, 1.06 and 1.03 Status-A density for red, green and blue. V29 replaced these with 1/1/1 and gave a vendor D60 LUT plus digitized curve residuals too much authority over final hue. V30 restores the official channel aims and sets both unsupported hue/saturation controls to zero.<Cite ids={["R4", "R48"]} /></p><div className="equation"><span>OFFICIAL LAD CONSTRAINT</span><b>D<sub>LAD</sub>=[1.09, 1.06, 1.03]　　w<sub>vendor-D60</sub>=w<sub>digitized-hue</sub>=w<sub>digitized-sat</sub>=0</b><small>Zeroing these weights retains structural evidence while refusing to promote unknown scan/digitization error into Kodak colour truth.</small></div><ol className="research-plan"><li><b>Three-scene holdout</b><span>T002, T020 and T032 each contribute 24 native 5760×4320 12-bit frames to both film observers.</span></li><li><b>Camera baseline</b><span>The same RAW receives only the necessary linear BT.2020→V-Gamut transform, V-Log encoding and Panasonic's official V-709 LUT—no 5279, 2383, scan or grade.<Cite ids={["R44", "R49"]} /></span></li><li><b>Neutral validation</b><span>Mean near-neutral projection chroma is 0.00107, 0.00455 and 0.00261; median observer hue difference is 4.80°, 4.99° and 3.95°.</span></li><li><b>Highlight boundary</b><span>T020/T032 camera baselines have no hard white clipping. About 1.4% of T002's bright sky reaches the V-709 endpoint; that belongs to the official camera view, not the 5279 shoulder.</span></li><li><b>Crash audit</b><span>Two Python observer threads can concurrently enter Numba's workqueue and trigger SIGABRT. The safe sequential default is pixel-identical in decoded RGB48.<Cite ids={["R50"]} /></span></li><li><b>Result</b><span>All three projections pass the neutral gate; rainy T032 retains its real cyan-green atmosphere instead of receiving a global magenta correction.</span></li></ol></section>

          <section id="v31-en"><div className="section-tag">18 · V31 · NORMAL-PROCESS CHROMA / TONE</div><h2>No silver was retained, yet the image read as bleach bypass</h2><p>Colour development forms dye and metallic-silver images at the same exposed sites, but normal ECN-2 and ECP-2D bleach and fix that silver away. Kodak separately identifies skip bleach, bleach bypass and ENR as special processes that increase contrast, darken shadows and reduce saturation. A normal 5279→2383 baseline should therefore not default to a strong retained-silver character.<Cite ids={["R3", "R51", "R52"]} /></p><p>V30 had no silver term. It expressed scan-referenced colour as C/L and then replaced L with the steeper 2383 neutral curve. Lower print lightness automatically removed absolute chroma while full-resolution luminance texture remained. Across the three matched scenes, V30 projection median chroma was about 12–17% below the scan, p90–p10 luminance span about 27–32% greater, and fine luminance texture about 48–60% stronger—the perceptual discriminator for a mild bleach-bypass result.</p><div className="equation"><span>V31 FINAL OBSERVER BOUNDARY</span><b>ab<sub>out</sub>=G<sub>σ</sub>＊ab<sub>scan</sub>+[ab<sub>proj</sub>−G<sub>σ</sub>＊ab<sub>proj</sub>]　·　Y<sub>out</sub>=Y<sub>proj</sub></b><small>Period 2K supplies only low-frequency dye colour; 2383 retains high-frequency opponent texture and all luminance. σ=0.72 px at 2K; no artistic saturation is added.</small></div><ol className="research-plan"><li><b>Texture locked</b><span>5279 grain, DIR, MTF, black, gamma, 2383 lightness and projection texture remain V30; 98.9–99.2% of fine luma texture is retained.</span></li><li><b>Validation</b><span>Projection/scan chroma retention is 91.1%, 93.3% and 89.2%; chroma saturation is 103.5%, 96.7% and 96.6%. All scan-master SHA-256 values are identical to V30.</span></li><li><b>Error record</b><span>Two earlier placements were bypassed by the hybrid branch and grain-mean stage and were rejected before release. The final correction runs after both complete observers.</span></li><li><b>Separate future toggle</b><span>Any future bypass variant must explicitly model residual silver density—not fake it with global contrast and saturation controls.</span></li></ol></section>

          <section id="evidence-audit-en"><div className="section-tag">15 · EVIDENCE AUDIT · 10 NOTES</div><h2>Ten hourly notes changed the evidence boundary—not the production model</h2><p>Hourly research was paused on 4 August 2026. Ten narrowly scoped notes audited DIR, ECN-2 controls, grain measurement, JVT document history and the patent-archive route. None supplied a new 5279 parameter that can be safely implemented, so the V27 production baseline remains unchanged.</p><div className="evidence-ledger"><article className="evidence-group"><span className="evidence-state confirmed">CONFIRMED</span><h3>What the records support</h3><ul><li>Kodak’s DIR diffusion factor is a compound assay, not a fixed 5279 cross-layer constant.</li><li>Green-only ECN-2 exposure is a causal exclusion control, not a transferable interimage coefficient.</li><li>The April 2003 provisional labels identifier 3 as 5279; May’s JVT-H022 labels it 5218. The document branch did drift.</li><li>The US 7,899,113 family was assigned by Thomson to Dolby effective at the end of 2016.<Cite ids={["R34", "R35", "R38", "R39", "R41", "R43"]} /></li></ul></article><article className="evidence-group"><span className="evidence-state denied">DISPROVED</span><h3>What cannot be claimed</h3><ul><li>H-24 process alarm/action limits are not measurement uncertainty.</li><li>One or finitely many 48 µm aperture RMS values cannot non-parametrically identify a continuous NPS.</li><li>A 5279 label or JVT model_id is not a published parameter table, LUT or grain spectrum.</li><li>Patent ownership does not establish custody of research mail, LUTs or lab records.<Cite ids={["R36", "R37", "R38", "R40", "R43"]} /></li></ul></article><article className="evidence-group"><span className="evidence-state unknown">UNKNOWN</span><h3>What public records still omit</h3><ul><li>The actual 5279 DIR compounds, placement, reaction–diffusion kinetics and cross-layer matrix.</li><li>A complete 5279 NPS, fast/mid/slow sublayer size distributions and physical scale.</li><li>Why the JVT example changed from 5279 to 5218 between April and May 2003.</li><li>The located public JVT mail evidence stops in 2002; Dolby custody of PU030116 working records is unproven.<Cite ids={["R42", "R43"]} /></li></ul></article></div><blockquote>The audit prevents patent examples, control limits and identifier history from being mistaken for a secret 5279 formula.</blockquote><p><b>Falsifiable next evidence:</b> frequency-resolved 5279 grain measurements, same-batch neutral/separation ECN-2 density pairs, or a contemporaneous PU030116 attachment with measurement metadata could test the NPS, interimage and stock-mapping hypotheses. Production parameters remain locked until such evidence exists.</p></section>

          <section id="limits-en"><div className="section-tag">16 · LIMITS</div><h2>What is known—and what remains unknowable</h2><ul><li><b>Direct:</b> published 5279 sensitometry, diffuse RMS granularity, MTF, sensitivity and net dye-density plots.</li><li><b>Mechanistic:</b> same-era Kodak multilayer, masking, DIR, ECN-2 and electronic-transfer documentation.</li><li><b>Still inferred:</b> actual 5279 per-sublayer size distributions, full Wiener/NPS curves, coating amounts, DIR compounds, diffusion constants and proprietary Spirit calibration.</li><li><b>Not recoverable from RGB:</b> original scene spectra, lens spectral transmission and chemical batch state.</li></ul><p>The model seeks a measurement-constrained physical approximation. It does not claim to recover Kodak’s undisclosed formula.</p></section>
          <section id="silver-efex-internals-en"><div className="section-tag">28 · SILVER EFEX · LOCAL ENGINE AUDIT</div><h2>Not prettier noise: finite grains form density</h2><p>A read-only audit of the locally installed Nik Collection 8 engine and resources confirms that every B&amp;W stock maps to a separate measured 1000×1000 texture. Tri-X 400, T-Max 100 and T-Max 400 have distinct spatial correlation, skew and kurtosis. The engine builds a deterministic 256×256 uniform lookup, then uses a 512×512 inverse-binomial-CDF table to turn pixel density <code>p</code> into a finite-grain realization.</p><div className="equation"><span>SILVER EFEX FINITE-GRAIN LOOKUP</span><b>G=F⁻¹<sub>Binomial(N,p)</sub>(u)/N　·　Y′=(1−α)Y+αG</b><small>This is not Y+noise; the stochastic grain candidate participates in forming the new pixel density.</small></div><p>A piecewise quartic lowers <code>α</code> to about 0.25 at absolute black and white. The shared colour path transports source chroma deterministically around the new luma rather than injecting independent RGB impulses. This directly supports V40&apos;s removal of duplicate high-frequency opponent colour and defines the V41 experiment: preserve 5279&apos;s three records, DIR, MTF and Kodak 48 µm boundary, but test a non-Gaussian correlated site field fitted to 5279 reference scans. Silver Efex&apos;s B&amp;W textures are evidence for architecture, never 5279 parameters.<Cite ids={["R63", "R64", "R65"]} /></p></section>
          <section id="v40-fsd-control-en"><div className="section-tag">29 · V40 · THREE-PIPELINE CONTROL</div><h2>FSD is an independent finite-density route—not a replacement for physical 5279</h2><p>The local Silver Efex audit revealed a testable image-formation architecture: a finite count of binary sites is converted to density through an inverse-binomial CDF and blended by an explicit endpoint taper. V40 reconstructs that architecture as <strong>Finite-Site Density (FSD)</strong>, without copying a B&amp;W stock texture or merging it into the three-record 5279 emulsion.<Cite ids={["R63", "R64", "R65"]} /></p><div className="equation"><span>FSD FINITE-SITE DENSITY</span><b>G=F⁻¹<sub>Binomial(N,p)</sub>(u)/N　　Y′=(1−α)Y+αG</b><small>N=176; 512² inverse-binomial CDF; σ=0.597 native pixels. Density forms in the post-observer sRGB signal domain while the deterministic opponent field remains fixed.</small></div><p>Calibrated on one T031 frame only, FSD versus the no-grain baseline has luma RMS 0.01820 against 0.01836 for physical V40, 99.9th-percentile absolute residual 0.10489 against 0.10032, and horizontal/vertical lag-1 0.43808/0.43831 against 0.43339/0.44406. Opponent-colour residual is deliberately lower—0.00152 against 0.00427—because FSD does not claim to reproduce three 5279 colour records or interlayer chemistry. T002 and T007 remain holdouts.</p><ol className="research-plan"><li><b>Physical 5279</b><span>V40 three records, fast/mid/slow populations, DIR, MTF, published 48 µm RMS and complete observers.</span></li><li><b>FSD</b><span>An independent test of finite sites forming density—not additive noise and not a claimed 5279 recipe.</span></li><li><b>Withdrawn implementation</b><span>The first version formed FSD in linear-RGB luma and scaled chroma at random gamut boundaries; sRGB encoding turned that into dark coloured impulses. The corrected version limits signal-density excursion only. Both isolated-spike levels are zero on the strongest T002 single-frame probe, without blur or desaturation.</span></li><li><b>Deterministic no-grain</b><span>The same RAW, colour, black, gamma and 2383 observer with stochastic sites replaced by expected density.</span></li><li><b>Failure gate</b><span>The inverse CDF accepts open-interval random values only, preventing the rare giant impulses caused by u=1; every frame is checked for primary spikes, tails and still/video identity.</span></li></ol></section>

          <section id="t003-chart-audit-en"><div className="section-tag">30 · T003 · CHART INPUT AUDIT</div><h2>The chart rejects a shared green error—and exposes five finer boundaries</h2><p>T003 is 5760×4320 ProRes RAW HQ; its metadata records the GH7, ISO 500 and fixed 5500 K. The target at frame 160 is identified as a DGK Color Tools DKC-Pro 5×7 and sampled against the manufacturer&apos;s published 18-patch CIELAB references. Patches 2–4, which the manufacturer recommends for RAW white balance, average R/G=1.175 and B/G=0.745 in Apple&apos;s standard extended-linear BT.2020/D65 decode. Their individual ratios span 1.91% and 1.20%. This is a stable warm as-shot direction, not an exposure-dependent green RAW error or missing file white-balance metadata.<Cite ids={["R45", "R47", "R66"]} /></p><div className="diagnostic-grid"><figure><img src={withBasePath("/research/t003-dkc-pro-sampling.jpg")} alt="Safe interior sampling locations for eighteen DGK DKC-Pro patches on T003 frame 160" /><figcaption>T003 frame 160: each row uses its own safe interior; the middle row excludes the printed title strip.</figcaption></figure></div><ol className="research-plan"><li><b>Gamma is still unidentifiable</b><span>Measured Y/reference Y across patches 2–5 spans 0.318 stops, but patch lightness is perfectly tied to left-to-right position. Illumination/reflection gradient and input nonlinearity cannot be separated, so the fitted 1.143 log slope must not enter the pipeline. Optical-flow tracking at seven times from frame 80 to 200 keeps the slope at 1.137–1.147 and the span at 0.304–0.323 stops: this rejects a one-frame accident but not the spatial confound.</span></li><li><b>This chart cannot calibrate black</b><span>The manufacturer&apos;s patch 6 reference is L*=23, not a zero-reflectance black trap. Its value includes real reflectance, ambient light and lens flare, so it cannot determine sensor offset or the finished-film black pedestal.</span></li><li><b>The highlight boundary is located</b><span>All three RAW white-patch channels exceed 1 and are not clamped at the display endpoint; only one channel of patch 1 reaches the official Panasonic V-709 endpoint. This limit belongs to the camera display witness—not RAW→5279 input.</span></li><li><b>Saturated cyan reaches a gamut boundary</b><span>Patch 10 creates a −0.01524 red component in the Rec.709-like film-light basis. The three combined 5279 record exposures would all remain positive, but V40 clips the basis first, raising the first record by 19.29% and moving scan/projection chromaticity by about Δu′v′ 0.00226/0.00203. This is a real pipeline boundary—not a RAW clip—and must be tested separately from V39&apos;s rejected stochastic model.</span></li><li><b>The input matrix remains a testable boundary</b><span>DKC-Pro rows are not equal height and a printed title strip precedes the middle row; the first equal-grid audit contaminated patches 7–12 and is withdrawn. With corrected sampling and an explicitly diagnostic D50/Bradford assumption, median hue error is 10.69° for saturated primaries and 7.75° for natural colours. Cross-group 3×3 tests reach median errors of 5.30° and 6.69°. An input-matrix residual is therefore plausible, but unknown scene SPD and reference-Lab conditions still cannot justify a production matrix.</span></li></ol><p>The DGK guide does not state the measurement illuminant/observer for its Lab triplets, and this frame contains directional daylight, target angle and surface reflection. V40 therefore adds no global magenta trim, automatic white balance, black offset or new camera matrix. The evidence supports a narrower conclusion: no fixed green cast is shared across the clips, and As Shot remains the default. The decisive retest is fixed exposure under uniform D65 and tungsten light, shooting both normal and 180-degree chart orientation plus brackets, plus a capped-lens/dark-trap capture: a slope that flips spatially is illumination; one that remains tied to reflectance triggers RAW-linearity and input-matrix audits.</p></section>
          <section id="t003-neutral-transport-en"><div className="section-tag">31 · T003 · NEUTRAL TRANSPORT THROUGH V40</div><h2>No shared neutral-green crossover, but warm offsets change with exposure</h2><p>After the corrected patches 2–5 pass through deterministic Period 2K and normal 2383, their chromaticity spread grows to 1.75× and 1.57× the input. Two four-level synthetic ramps remove the outdoor illumination gradient while keeping chromaticity exactly constant.</p><ol className="research-plan"><li><b>D65-neutral ramp passes</b><span>Maximum Δu′v′ is only 0.000174 in scan and 0.000155 in projection; the pipeline does not manufacture a shared neutral-to-green crossover.</span></li><li><b>Constant warm ramp crosses with exposure</b><span>The same warm chromaticity reaches maximum Δu′v′ 0.002530 in scan and 0.002204 in projection; brightest-to-darkest distances are 0.004294 and 0.003620.</span></li><li><b>Evidence boundary</b><span>A three-record negative can reproduce off-neutral colour nonlinearly, so the existence of this effect is not automatically an error. Its current magnitude is model-derived and lacks a matched controlled 5279 measurement.</span></li></ol><p>No grade or global matrix is used to hide it. The next test needs controlled D65/tungsten light, matched GH7 and same-batch 5279 exposure ramps, and high-resolution scans to measure the real off-neutral crossover.</p></section>
        </article>
      </div>

      <section id="references" className="references"><div className="section-tag">REFERENCES</div><h2>Sources and citations</h2><ol>{references.map((ref) => <li id={`ref-${ref.id}`} key={ref.id}><span>{ref.id.slice(1).padStart(2, "0")}</span><div><a href={ref.url} target="_blank" rel="noreferrer">{ref.title}</a><small>{referenceTypeEnglish(ref.type)}</small></div></li>)}</ol></section>
    </main>
  );
}
